from pydantic import BaseModel, Field, ValidationError
from enum import Enum

class OrderAction(str, Enum):
    query = 'query'
    cancel = 'cancel'

class OrderArgs(BaseModel):
    action: OrderAction
    order_id: str = Field(pattern=r'^SO\d{10}$')
    reason: str | None = Field(default=None, max_length=200)

WRITE_ACTIONS = {OrderAction.cancel}

def execute_tool(name: str, raw: dict, ctx) -> dict:
    if name != 'order_op':
        return {'ok': False, 'error': 'unknown_tool'}
    try:
        args = OrderArgs(**raw)
    except ValidationError as e:
        return {'ok': False, 'error': 'invalid_args', 'detail': e.errors()}
    if args.action in WRITE_ACTIONS:
        if not ctx.has_permission('order:write'):
            return {'ok': False, 'error': 'forbidden'}
        key = f'{ctx.trace_id}:{name}:{args.action}:{args.order_id}'
        if not ctx.idempotency.acquire(key):
            return {'ok': False, 'error': 'duplicate'}
        return ctx.apply(args)
    return ctx.read(args)

import hashlib, json

def task_sig(goal: str, constraints: dict) -> str:
    norm = json.dumps({'goal': goal.strip(), 'c': constraints}, sort_keys=True, ensure_ascii=False)
    return hashlib.sha1(norm.encode()).hexdigest()[:12]

def delegate(parent, callee: str, goal: str, constraints: dict) -> dict:
    sig = task_sig(goal, constraints)
    path = parent.delegation_path + [(callee, sig)]
    if (callee, sig) in parent.delegation_path:
        return {'status': 'cycle_detected', 'path': path, 'action': 'escalate'}
    if len(path) > parent.limits.max_depth:
        return {'status': 'depth_exceeded', 'path': path, 'action': 'escalate'}
    child_budget = parent.budget.spend_child()
    if child_budget.remaining_steps <= 0:
        return {'status': 'budget_exhausted', 'path': path, 'action': 'summarize_partial'}
    return callee.run(goal=goal, constraints=constraints,
                      delegation_path=path, budget=child_budget,
                      trace_id=parent.trace_id)

import time

LEASE_TTL = 15.0            # 由该阶段 p99 单步耗时推导，不用全局常量
RENEW_EVERY = LEASE_TTL / 3

class LeaseLost(Exception):
    pass

def renew_loop(redis, task_id, worker_id, stop_evt):
    key = f"lease:{task_id}"
    while not stop_evt.is_set():
        ok = redis.eval(
            "if redis.call('get', KEYS[1])==ARGV[1] then "
            "return redis.call('expire', KEYS[1], ARGV[2]) else return 0 end",
            1, key, worker_id, int(LEASE_TTL))
        if not ok:
            raise LeaseLost(task_id)      # 已被接管，立刻停手，不写任何状态
        stop_evt.wait(RENEW_EVERY)

def take_over(redis, task_id, new_worker):
    # 原子抢占并递增 fence，旧持有者的写入会被存储侧拒绝
    lua = ("local cur = redis.call('get', KEYS[1]) "
           "if cur then return -1 end "
           "local f = redis.call('incr', KEYS[2]) "
           "redis.call('set', KEYS[1], ARGV[1], 'EX', ARGV[2]) "
           "return f")
    return redis.eval(lua, 2, f"lease:{task_id}", f"fence:{task_id}",
                      new_worker, int(LEASE_TTL))

def write_with_fence(store, task_id, fence, payload):
    return store.cas_write(task_id, payload, min_fence=fence)

import asyncio

READ_ONLY = {"search_docs", "get_order", "query_stock"}

def schedule(tool_calls):
    plan, batch = [], []
    for c in tool_calls:
        if c.name in READ_ONLY:
            batch.append(c)
            continue
        if batch:
            plan.append(("parallel", batch)); batch = []
        plan.append(("serial", [c]))
    if batch:
        plan.append(("parallel", batch))
    return plan

async def run(plan, ctx):
    results = {}
    for mode, calls in plan:
        if mode == "parallel":
            done = await asyncio.gather(*(read(c, ctx) for c in calls),
                                        return_exceptions=True)
        else:
            done = [await write_idempotent(calls[0], ctx)]
        for c, r in zip(calls, done):
            results[c.id] = r      # 失败同样回填，交由模型决策而非自动重放
    return results

def key_of(task_id, step, call):
